#include <cmath>
#include <iostream>
#include <string_view>

struct Point
{
    double x{};
    double y{};
};

Point readPoint(std::string_view prompt)
{
    std::cout << prompt;
    Point p{};
    std::cin >> p.x >> p.y;
    return p;
}

double distance(const Point& a, const Point& b)
{
    const double dx{ b.x - a.x };
    const double dy{ b.y - a.y };
    return std::sqrt(dx * dx + dy * dy);
}

